Class.css:
.ftml-assertion-theorem {
  & .ftml-title-paragraph {
    font-weight: bold;
    font-size: inherit;
    display: inline-block;

    &:before {
      content: "Theorem" " "counter(ftml-section) "." counter(ftml-para);
    }

    &:after {
      content: ". ";
    }
  }
}

